From 7de30d35320699360bbc63d4ccdb250c01a674cd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:12:34 +0100
Subject: [PATCH] applets/pager: follow the global wrap-around setting when
 scrolling

The pager had its own "Navigation wraps around" option for scrolling,
which could disagree with the virtual desktop setting used by keyboard
switching. Use the global one and keep the option only for activities.

BUG: 460806
---
 applets/pager/qml/configGeneral.qml |  1 +
 applets/pager/qml/main.qml          | 11 +++++++++--
 2 files changed, 10 insertions(+), 2 deletions(-)

diff --git a/applets/pager/qml/configGeneral.qml b/applets/pager/qml/configGeneral.qml
index 23074d9ab6..1e9c0d9108 100644
--- a/applets/pager/qml/configGeneral.qml
+++ b/applets/pager/qml/configGeneral.qml
@@ -55,6 +55,7 @@ KCM.SimpleKCM {
         QQC2.CheckBox {
             id: wrapPage
             text: i18nc("@option:check", "Navigation wraps around")
+            visible: root.isActivityPager
         }


diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..712224239d 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -16,6 +16,7 @@ import org.kde.plasma.components as PlasmaComponents3
 import org.kde.draganddrop as DnD
 import plasma.applet.org.kde.plasma.pager
 import org.kde.plasma.activityswitcher as ActivitySwitcher
+import org.kde.taskmanager as TaskManager
 import org.kde.kirigami as Kirigami

 import org.kde.kcmutils as KCM
@@ -50,6 +51,8 @@ PlasmoidItem {

     property int wheelDelta: 0

+    readonly property bool wrapPage: isActivityPager ? Plasmoid.configuration.wrapPage : virtualDesktopInfo.navigationWrappingAround
+
     function colorWithAlpha(color: color, alpha: real): color {
         return Qt.rgba(color.r, color.g, color.b, alpha)
     }
@@ -116,7 +119,7 @@ PlasmoidItem {

             while (increment !== 0) {
                 if (increment < 0) {
-                    const nextPage = Plasmoid.configuration.wrapPage?
+                    const nextPage = root.wrapPage ?
                         (pagerModel.currentPage + 1) % repeater.count :
                         Math.min(pagerModel.currentPage + 1, repeater.count - 1);
                     // At the last desktop: changePage() on the current one would toggle Show Desktop
@@ -124,7 +127,7 @@ PlasmoidItem {
                         pagerModel.changePage(nextPage);
                     }
                 } else {
-                    const previousPage = Plasmoid.configuration.wrapPage ?
+                    const previousPage = root.wrapPage ?
                         (repeater.count + pagerModel.currentPage - 1) % repeater.count :
                         Math.max(pagerModel.currentPage - 1, 0);
                     if (previousPage !== pagerModel.currentPage) {
@@ -138,6 +141,10 @@ PlasmoidItem {
         }
     }

+    TaskManager.VirtualDesktopInfo {
+        id: virtualDesktopInfo
+    }
+
     PagerModel {
         id: pagerModel

-- 
2.53.0
